from odoo import api, fields, models


class ResCompany(models.Model):
    _inherit = 'res.company'

    regie_communication_prefix = fields.Char(
        string="Structured Communication Prefix", default='9',
        help="Leading digit(s) of the structured communications of the leases, to keep them apart "
             "from the references generated by Odoo for invoices.",
    )

    # ------------------------------------------------------------
    # DEMO
    # ------------------------------------------------------------

    @api.model
    def _regie_demo_archive_previous_company(self):
        """ Demo: after an uninstall, the previous demo company cannot be deleted (it has a chart of
        accounts) and loses its xml id. Archive and rename it so that a reinstall starts clean. """
        if self.env.ref('regie_fonciere.demo_company', raise_if_not_found=False):
            return
        previous = self.search([('name', '=', "Régie foncière (démo)")])
        previous = previous.filtered(lambda c: not c.get_external_id().get(c.id))
        for company in previous:
            users = self.env['res.users'].with_context(active_test=False).search([('company_ids', 'in', company.id)])
            for user in users.filtered(lambda u: u.company_id != company):
                user.company_ids = [(3, company.id)]
            company.write({
                'name': "Régie foncière (démo, %s)" % fields.Datetime.now().strftime('%Y-%m-%d %H:%M'),
                'active': False,
            })

    @api.model
    def _regie_demo_setup_company(self):
        """ Demo: load the Belgian chart of accounts on the demo company and give
        the administrator access to it. Idempotent (called again on each update). """
        company = self.env.ref('regie_fonciere.demo_company', raise_if_not_found=False)
        if not company:
            return
        if not company.chart_template:
            # _load() rather than try_loading(): the latter warns when the registry is not fully
            # loaded unless the chart's own demo (sample invoices) is installed, which we don't want.
            self.env['account.chart.template']._load('be_comp', company, install_demo=False)
        for user in (self.env.ref('base.user_admin'), self.env.ref('base.user_root')):
            if company not in user.company_ids:
                user.company_ids = [(4, company.id)]
